import type {FlowPageInstanceStructureKind} from "./flow-graph/page-instance-structure.js";

export interface ComposedRowsContext {
  dom:Document;model:ComposedSchemaWorkspace;effectiveText:(row:ComposedSchemaRow)=>string;onRepair?:((repair:ComposedSchemaRepair)=>void)|undefined;rowPathDataset?:string|undefined;
  activePath:string|undefined;activeSection:FocusedPropertySection;draft:ComposedFacetDraft|undefined;removed:boolean;removedRuleIds:Set<string>;overriddenRuleIds:Set<string>;overrideRule:(index:number)=>void;
  pendingAction:"reset"|"remove"|undefined;beginAction:(row:ComposedSchemaRow,focus?:HTMLElement)=>void;cancelAction:()=>void;confirmAction:(row:ComposedSchemaRow)=>void;
  open:(row:ComposedSchemaRow,focus?:HTMLElement,section?:FocusedPropertySection)=>void;close:()=>void;save:(row:ComposedSchemaRow)=>void;render:()=>void;setActiveSection:(section:FocusedPropertySection)=>void;
  onStructure?:(kind:FlowPageInstanceStructureKind,path:string,name?:string)=>void|undefined;
}
const button=(dom:Document,text:string,run:()=>void):HTMLButtonElement=>{const control=dom.createElement("button");control.type="button";control.textContent=text;control.addEventListener("click",run);return control;};
const actionText=(row:ComposedSchemaRow):string=>row.action==="override"?"Override here":row.action==="reset"?"Reset to parents":"Remove local property";

function contextMenu(row:ComposedSchemaRow,context:ComposedRowsContext):HTMLElement {
  const {dom}=context,menu=dom.createElement("div");menu.setAttribute("role","menu");menu.setAttribute("aria-label",`${row.path} property context menu`);menu.dataset.propertyContextMenu="true";
  for(const sectionName of focusedPropertySections){const entry=dom.createElement("div"),choose=button(dom,focusedPropertySectionLabels[sectionName],()=>{context.setActiveSection(sectionName);context.render();}),details=dom.createElement("span");entry.dataset.section=sectionName;details.textContent=sectionName==="values"?`${(context.draft?.allowedValues??row.local.allowedValues??row.effective.allowedValues??[]).length} allowed values`:sectionName==="rules"?`${(context.draft?.rules??[]).length} rules`:"View effective value";entry.append(choose,details);menu.append(entry);}
  const ownership=dom.createElement("div"),local=Object.keys(row.local).some((key)=>key!=="path"),inherited=Boolean(row.inherited),actions=focusedOwnershipActions({local,inherited,overridden:row.action==="reset",invariant:row.effective.enforcement==="invariant",conflict:row.validationState==="blocked",replaceable:row.effective.enforcement!=="invariant"});
  for(const action of actions){const control=button(dom,action,()=>{if(action==="Remove local"||action==="Reset to parent"){context.beginAction(row);return;}if(action==="Override here"||action==="Replace here")context.setActiveSection("definition");context.render();});control.dataset.ownershipAction=action;ownership.append(control);}menu.append(ownership);return menu;
}

function focused(row:ComposedSchemaRow,context:ComposedRowsContext):HTMLElement {
  const {dom}=context,editor=dom.createElement("section"),heading=dom.createElement("h3"),identity=dom.createElement("p"),effective=dom.createElement("p"),host=dom.createElement("section"),actions=dom.createElement("div");editor.setAttribute("aria-label",`${row.path} focused property editor`);editor.dataset.focusedPropertyEditor="true";heading.textContent=`Focused property · ${row.path}`;identity.textContent=`${row.path} · stable identity ${row.effective.definitionId??row.path}`;effective.textContent=`Inherited value and source: ${row.inherited?context.effectiveText({...row,effective:row.inherited}):"none"} · Effective result: ${context.effectiveText(row)} · validation ${row.validationState} · conflicts ${row.validationState==="blocked"?row.message:"none"}`;host.setAttribute("aria-label",`${row.path} focused ${focusedPropertySectionLabels[context.activeSection]} section`);const focusedContext={model:context.model,dom,row,getDraft:()=>context.draft,activeSection:context.activeSection,removedRuleIds:context.removedRuleIds,overriddenRuleIds:context.overriddenRuleIds,overrideRule:context.overrideRule,render:context.render,...(context.onStructure?{onStructure:context.onStructure}: {})};renderComposedFocusedSection(host,focusedContext);if(context.pendingAction){const impact=dom.createElement("p");impact.setAttribute("aria-label","Property impact review");impact.textContent=`${context.pendingAction==="reset"?"Reset":"Remove"} preview · prospective effective result ${row.inherited?context.effectiveText({...row,effective:row.inherited}):"none"} · affected Page instances recompile · outputs become stale · one Undo action remains available.`;actions.append(impact,button(dom,context.pendingAction==="reset"?"Cancel reset":"Cancel removal",context.cancelAction),button(dom,context.pendingAction==="reset"?"Confirm reset to parents":"Confirm remove local property",()=>context.confirmAction(row)));}else actions.append(button(dom,"Cancel",context.close),button(dom,"Review changes",()=>{const review=dom.createElement("p");review.setAttribute("aria-label","Review changes");review.textContent=`Review changes · ${row.path} · prospective effective result ${context.effectiveText(row)} · affected consumers recompile`;actions.replaceChildren(review,button(dom,"Cancel review",context.render),button(dom,"Confirm changes",()=>context.save(row)));}),button(dom,"Save property",()=>context.save(row)));editor.append(heading,identity,effective,host,actions);return editor;
}

export function renderComposedRows(rows:HTMLElement,context:ComposedRowsContext):void {
  rows.replaceChildren();for(const row of context.model.rows){const article=context.dom.createElement("article"),overview=context.dom.createElement("div"),toggle=context.dom.createElement("button"),effective=context.dom.createElement("span"),source=context.dom.createElement("span"),local=context.dom.createElement("span"),validation=context.dom.createElement("span"),actions=context.dom.createElement("div"),primary=button(context.dom,actionText(row),()=>row.action==="override"?context.open(row,primary):context.beginAction(row,primary)),propertyActions=button(context.dom,"Property actions",()=>context.open(row,propertyActions));article.className="composed-schema-row";article.dataset.effectivePropertyPath=row.path;if(context.rowPathDataset)article.dataset[context.rowPathDataset]=row.path;article.dataset.validationState=row.validationState;toggle.className="composed-schema-row-toggle";toggle.textContent=row.path;toggle.setAttribute("aria-expanded",String(context.activePath===row.path));toggle.addEventListener("click",()=>context.activePath===row.path?context.close():context.open(row,toggle));effective.textContent=context.effectiveText(row)||"constraint";source.textContent=row.source;local.textContent=context.removed&&context.activePath===row.path?"Removed":Object.keys(row.local).length>1?JSON.stringify(row.local):"Inherited";validation.textContent=`${row.validationState} · ${row.message}`;actions.className="composed-schema-row-actions";propertyActions.setAttribute("aria-label",`Property actions for ${row.path}`);actions.append(primary,propertyActions);overview.append(toggle,effective,source,local,validation,actions);article.append(overview);if(context.onRepair)for(const repair of row.repairs)article.append(button(context.dom,repair.label,()=>context.onRepair?.(repair)));if(context.activePath===row.path)article.append(contextMenu(row,context),focused(row,context));rows.append(article);}
}
